-- Imported from gitpage/static/tmath/scenes-on-thorvg/frame-scene.lua.
-- Original tiger image embedded as RGBA pixels for standalone browser playback.
-- Adapted from static/img/scenes-on-thorvg/frametree.gif.
-- Top: the tree built once and added to the canvas once.
-- Bottom: the calls made every frame. Only the dot's translate and scale change;
-- the tree itself is never rebuilt.
-- Review beats: t=0, 2.5, 5, 7.5, 10. All values return to the opening state.
local W,H,FPS,DURATION=1200,675,24,10
local scene=tmath.scene{width=W,height=H,fps=FPS,loop=true,
    theme={preset="adaptive_vscode"},camera={mode="fixed",view="2d",height=H}}
local function p(x,y) return {x-W/2,H/2-y} end
local function matrix(x,y,s)
    local q=p(x,y);s=s or 1
    return {s,0,0,q[1],0,s,0,q[2],0,0,1,0,0,0,0,1}
end
local function text(id,value,x,y,size,color,opacity)
    return scene:text{id=id,text=value,point=p(x,y),font="CMUTypewriter-Regular",
        role="code",size=size or 24,align={0,0.5},fill=color or "foreground",
        opacity=opacity==nil and 1 or opacity,layer=50}
end
local function line(id,x1,y1,x2,y2,color,width)
    return scene:line{id=id,from=p(x1,y1),to=p(x2,y2),stroke=color or "border",width=width or 1,layer=15}
end
local function state(u)
    local t=(1-math.cos(2*math.pi*u))/2
    return {t=math.floor(t*100+0.5),x=math.floor(40+240*t+0.5),
        y=math.floor(120-65*math.sin(2*math.pi*t)+0.5),
        r=math.floor(11+7*math.sin(math.pi*t)+0.5)}
end
local first=state(0)

-- Built once.
local TREE,ROW=19,25
local ADV=TREE*0.7
text("canvas","SwCanvas",44,52,TREE)
text("add","add(root)",44+9*ADV,52,TREE,"muted")
text("root","Scene",72,52+ROW,TREE)
local rows={
    {"background","Shape   appendRect",100,2},
    {"curve","Shape   moveTo, lineTo",100,3},
    {"dot","Shape   appendCircle(0, 0, 1, 1)",100,4,"foreground"},
    {"label","Text    \"sin x\"",100,5},
    {"picture","Picture frame-tiger.png",100,6},
    {"group","Scene   transform",100,7},
    {"square","Shape appendRect",128,8},
    {"circle1","Shape appendCircle",128,9},
    {"circle2","Shape appendCircle",128,10},
}
for _,row in ipairs(rows) do text(row[1],row[2],row[3],52+row[4]*ROW,TREE,row[5] or "muted") end
text("dot-name","// dot",100+34*ADV,52+4*ROW,TREE,"accent")
line("root-tree",54,62,54,52+ROW)
line("root-branch",54,52+ROW,67,52+ROW)
line("children-tree",82,52+ROW+10,82,52+7*ROW)
for i=2,7 do line("branch-"..i,82,52+i*ROW,95,52+i*ROW) end
line("group-tree",110,52+7*ROW+10,110,52+10*ROW)
for i=8,10 do line("group-branch-"..i,110,52+i*ROW,123,52+i*ROW) end

line("split",44,328,660,328,"border",1)

-- Every frame.
local CODE,STEP=22,32
local CADV=CODE*0.7
local Y0=366
text("loop","for (t : frames) {",44,Y0,CODE,"muted")
local IND=44+4*CADV
text("translate-open","dot->translate(",IND,Y0+STEP,CODE)
text("translate-comma",",",IND+18*CADV,Y0+STEP,CODE)
text("translate-close",");",IND+23*CADV,Y0+STEP,CODE)
text("scale-open","dot->scale(",IND,Y0+2*STEP,CODE)
text("scale-close",");",IND+13*CADV,Y0+2*STEP,CODE)
text("update","canvas->update();",IND,Y0+3*STEP,CODE,"muted")
text("draw","canvas->draw(true);",IND,Y0+4*STEP,CODE,"muted")
text("sync","canvas->sync();",IND,Y0+5*STEP,CODE,"muted")
text("loop-close","}",44,Y0+6*STEP,CODE,"muted")

local digits={}
local function number(id,x,y,count,value,size,color,advance,pad)
    local fmt=(pad and "%0" or "%")..count.."d"
    local handles={};local str=string.format(fmt,value)
    for slot=1,count do
        local current=tonumber(str:sub(slot,slot));local list={}
        for digit=0,9 do
            list[digit]=text(id.."-"..slot.."-"..digit,tostring(digit),x+(slot-1)*advance,y,
                size,color,digit==current and 1 or 0)
        end
        handles[slot]={list=list,current=current}
    end
    digits[id]={handles=handles,fmt=fmt}
end
number("cx",IND+15*CADV,Y0+STEP,3,first.x,CODE,"accent",CADV)
number("cy",IND+20*CADV,Y0+STEP,3,first.y,CODE,"accent",CADV)
number("r",IND+11*CADV,Y0+2*STEP,2,first.r,CODE,"accent",CADV)

scene:rectangle{id="surface",center=p(930,288),size={452,336},
    fill="background",stroke="border",width=1,layer=10}
local originX,originY=733,165
local scale=1.2
local curvePoints={}
for i=0,120 do
    local t=i/120
    curvePoints[#curvePoints+1]=p(originX+scale*(40+240*t),originY+scale*(120-65*math.sin(2*math.pi*t)))
end
