local function numberChanges(id,value,changes)
    local spec=digits[id];local str=string.format(spec.fmt,value)
    for slot,entry in ipairs(spec.handles) do
        local digit=tonumber(str:sub(slot,slot))
        if digit~=entry.current then
            if entry.current~=nil then changes[#changes+1]={target=entry.list[entry.current],opacity=0} end
            if digit~=nil then changes[#changes+1]={target=entry.list[digit],opacity=1} end
            entry.current=digit
        end
    end
end
local frames=DURATION*FPS
for frame=1,frames do
    local s=state(frame/frames)
    local changes={{target=circle,transform=matrix(originX+scale*s.x,originY+scale*s.y,scale*s.r)},
        {target=cursor,transform=matrix(704+452*s.t/100,605)}}
    numberChanges("cx",s.x,changes);numberChanges("cy",s.y,changes)
    numberChanges("r",s.r,changes)
    numberChanges("time-integer",math.floor(s.t/100),changes)
    numberChanges("time-fraction",s.t%100,changes)
    scene:wait(1/FPS-0.001)
    scene:play(changes,0.001,"linear")
end
scene:wait(1/FPS)
return scene
